-- LE.FIND / banco relacional MySQL-compatible
-- Para Supabase/PostgreSQL, adapte AUTO_INCREMENT, ENUM e nomes antes de executar.

CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, openId VARCHAR(64) NOT NULL UNIQUE, name TEXT, email VARCHAR(320), loginMethod VARCHAR(64), role ENUM('user','admin') NOT NULL DEFAULT 'user', createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, lastSignedIn TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles (id INT AUTO_INCREMENT PRIMARY KEY, userId INT NULL, slug VARCHAR(140) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, role VARCHAR(160) NOT NULL, bio TEXT, city VARCHAR(120) NOT NULL, neighborhood VARCHAR(120), avatarUrl TEXT, coverUrl TEXT, verified INT NOT NULL DEFAULT 0, gold INT NOT NULL DEFAULT 0, sos INT NOT NULL DEFAULT 0, availability ENUM('open','next','full') NOT NULL DEFAULT 'open', rating DECIMAL(3,2) NOT NULL DEFAULT 0, reviewCount INT NOT NULL DEFAULT 0, socialsJson JSON NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stores (id INT AUTO_INCREMENT PRIMARY KEY, ownerId INT NULL, name VARCHAR(180) NOT NULL, category VARCHAR(100) NOT NULL, city VARCHAR(120) NOT NULL, neighborhood VARCHAR(120), description TEXT, imageUrl TEXT, productsJson JSON NULL, sponsored INT NOT NULL DEFAULT 0, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS communities (id INT AUTO_INCREMENT PRIMARY KEY, ownerId INT NULL, slug VARCHAR(140) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, visibility ENUM('public','private') NOT NULL DEFAULT 'private', city VARCHAR(120) NOT NULL, description TEXT, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS communityMembers (id INT AUTO_INCREMENT PRIMARY KEY, communityId INT NOT NULL, profileId INT NOT NULL, status ENUM('pending','approved','blocked') NOT NULL DEFAULT 'pending', createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY communityProfile (communityId, profileId));
CREATE TABLE IF NOT EXISTS reviews (id INT AUTO_INCREMENT PRIMARY KEY, profileId INT NOT NULL, authorName VARCHAR(160) NOT NULL, rating TINYINT NOT NULL, body TEXT NOT NULL, verified INT NOT NULL DEFAULT 1, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quotes (id INT AUTO_INCREMENT PRIMARY KEY, profileId INT NULL, storeId INT NULL, requesterName VARCHAR(160) NOT NULL, requesterPhone VARCHAR(40), description TEXT NOT NULL, status ENUM('new','contacted','closed') NOT NULL DEFAULT 'new', createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sponsoredSpots (id INT AUTO_INCREMENT PRIMARY KEY, storeId INT NOT NULL, keyword VARCHAR(120) NOT NULL, region VARCHAR(160) NOT NULL, budgetCents INT NOT NULL DEFAULT 0, startsAt TIMESTAMP NULL, endsAt TIMESTAMP NULL, status ENUM('draft','active','paused','finished') NOT NULL DEFAULT 'draft', createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS serviceReports (id INT AUTO_INCREMENT PRIMARY KEY, profileId INT NOT NULL, slug VARCHAR(140) NOT NULL UNIQUE, title VARCHAR(180) NOT NULL, summary TEXT, beforeUrl TEXT, afterUrl TEXT, checklistJson JSON NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS payments (id INT AUTO_INCREMENT PRIMARY KEY, provider VARCHAR(32) NOT NULL DEFAULT 'stripe', providerPaymentId VARCHAR(255) NULL UNIQUE, providerEventId VARCHAR(255) NULL, userId INT NULL, profileId INT NULL, storeId INT NULL, productType ENUM('gold','sponsored_spot') NOT NULL, amountCents INT NOT NULL, currency VARCHAR(8) NOT NULL DEFAULT 'brl', method ENUM('pix','card') NOT NULL DEFAULT 'card', status ENUM('pending','approved','failed','refunded','canceled') NOT NULL DEFAULT 'pending', metadataJson TEXT NULL, paidAt TIMESTAMP NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS paymentEvents (id INT AUTO_INCREMENT PRIMARY KEY, provider VARCHAR(32) NOT NULL DEFAULT 'stripe', eventId VARCHAR(255) NOT NULL UNIQUE, eventType VARCHAR(120) NOT NULL, processedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS entitlements (id INT AUTO_INCREMENT PRIMARY KEY, targetKey VARCHAR(220) NOT NULL UNIQUE, kind ENUM('gold','sponsored_spot') NOT NULL, profileId INT NULL, storeId INT NULL, paymentId INT NULL, status ENUM('active','revoked','expired') NOT NULL DEFAULT 'revoked', source ENUM('payment','manual') NOT NULL DEFAULT 'payment', manualOverride ENUM('none','grant','revoke') NOT NULL DEFAULT 'none', overrideByUserId INT NULL, overrideReason VARCHAR(255) NULL, startsAt TIMESTAMP NULL, endsAt TIMESTAMP NULL, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);

CREATE INDEX idxProfilesCity ON profiles(city); CREATE INDEX idxProfilesSos ON profiles(sos); CREATE INDEX idxSpotsKeywordRegion ON sponsoredSpots(keyword, region); CREATE INDEX idxPaymentsStatus ON payments(status); CREATE INDEX idxEntitlementsKindStatus ON entitlements(kind, status);
